<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowLeft, CopyDocument, Delete, Document, Download, EditPen, FullScreen, Refresh, RefreshRight, SetUp, Setting, WarningFilled } from '@element-plus/icons-vue'
import { parse, stringify } from 'yaml'
import { Terminal } from 'xterm'
import { FitAddon } from 'xterm-addon-fit'
import 'xterm/css/xterm.css'
import KubernetesYamlEditor from '@/components/KubernetesYamlEditor.vue'
import { applyKubernetesObject, deleteKubernetesObject, execKubernetesPodCommand, getKubernetesDeploymentSupport, getKubernetesObject, getKubernetesPodLogs, listKubernetesEvents, listKubernetesObjects, type KubernetesDeploymentSupport, type KubernetesEvent, type KubernetesObject } from '@/api/kubernetes'

const route = useRoute(), router = useRouter()
const clusterID = computed(() => Number(route.query.cluster_id || 0))
const namespace = computed(() => String(route.query.namespace || 'default'))
const name = computed(() => String(route.query.name || ''))
const loading = ref(false), activeTab = ref('overview'), yaml = ref(''), row = ref<KubernetesObject | null>(null)
const manifest = ref<any>({}), pods = ref<KubernetesObject[]>([]), events = ref<KubernetesEvent[]>([])
const yamlDialog = ref(false), saving = ref(false)
const describeDialog = ref(false), yamlMode = ref<'edit' | 'clone'>('edit')
const scaleDialog = ref(false), scaleReplicas = ref(0), scaleSaving = ref(false)
const deleteDialog = ref(false), deleting = ref(false), deleteConfirm = ref(''), deleteWait = ref(true), deleteForce = ref(false)
const editorYaml = ref('')
const support = ref<KubernetesDeploymentSupport>({ related: [], history: [], metrics: [], owner: '', uid: '', revision: '', min_ready_seconds: 0, progress_deadline_seconds: null, description: '' })
const logPod = ref('__all__'), terminalPod = ref(''), terminalContainer = ref(''), logs = ref(''), logsLoading = ref(false)
const commandRunning = ref(false)
const podPage = ref(1), podPageSize = ref(10)
const historyPage = ref(1), historyPageSize = ref(10)
const expandedContainers = ref<Record<string, boolean>>({})
const logFilter = ref(''), logWrap = ref(false), logGreen = ref(true), logPanel = ref<HTMLElement>()
const logTailLines = ref(100), logTimestamps = ref(false), logFontSize = ref(12)
const terminalHost = ref<HTMLElement>(), terminalPanel = ref<HTMLElement>(), terminalFontSize = ref(12), terminalUp = ref(0), terminalDown = ref(0)
let xterm: Terminal | undefined, xtermFit: FitAddon | undefined, terminalBuffer = '', terminalSessionKey = '', terminalResizeObserver: ResizeObserver | undefined

const spec = computed(() => manifest.value?.spec || {})
const metadata = computed(() => manifest.value?.metadata || {})
const containers = computed<any[]>(() => spec.value?.template?.spec?.containers || [])
const labels = computed<Record<string, string>>(() => metadata.value?.labels || {})
const annotations = computed<Record<string, string>>(() => metadata.value?.annotations || {})
const selector = computed<Record<string, string>>(() => spec.value?.selector?.matchLabels || {})
const desired = computed(() => Number(spec.value?.replicas ?? 1))
const ready = computed(() => Number((row.value?.ready || '0/0').split('/')[0] || 0))
const available = computed(() => ['Running', 'Available', 'Ready', '可用'].includes(row.value?.status || '') ? ready.value : 0)
const deploymentEvents = computed(() => {
  const podNames = new Set(pods.value.map(pod => pod.name))
  const replicaSetNames = new Set(support.value.history.map(item => item.name))
  return events.value.filter(item => {
    const kind = item.involvedObject.kind.toLowerCase()
    const resourceName = item.involvedObject.name
    return (kind === 'deployment' && resourceName === name.value)
      || (kind === 'replicaset' && replicaSetNames.has(resourceName))
      || (kind === 'pod' && podNames.has(resourceName))
  })
})
const strategy = computed(() => spec.value?.strategy?.type || 'RollingUpdate')
const maxSurge = computed(() => spec.value?.strategy?.rollingUpdate?.maxSurge ?? '-')
const maxUnavailable = computed(() => spec.value?.strategy?.rollingUpdate?.maxUnavailable ?? '-')
const serviceAccount = computed(() => spec.value?.template?.spec?.serviceAccountName || 'default')
const volumes = computed(() => (spec.value?.template?.spec?.volumes || []).length)
const pagedPods = computed(() => pods.value.slice((podPage.value - 1) * podPageSize.value, podPage.value * podPageSize.value))
const sortedHistory = computed(() => [...support.value.history].sort((left, right) => Number(right.revision || 0) - Number(left.revision || 0)))
const pagedHistory = computed(() => sortedHistory.value.slice((historyPage.value - 1) * historyPageSize.value, historyPage.value * historyPageSize.value))
const podMetricMap = computed(() => new Map(support.value.metrics.map(item => [item.pod, item])))
function cpuNumber(value?: string) { if (!value) return 0; return value.includes('Core') ? Number.parseFloat(value) * 1000 : Number.parseFloat(value) || 0 }
function memoryNumber(value?: string) { if (!value) return 0; return value.includes('GiB') ? Number.parseFloat(value) * 1024 : Number.parseFloat(value) || 0 }
const maxPodCPU = computed(() => Math.max(1, ...support.value.metrics.map(item => cpuNumber(item.cpu))))
const maxPodMemory = computed(() => Math.max(1, ...support.value.metrics.map(item => memoryNumber(item.memory))))
const filteredLogs = computed(() => logs.value.split('\n').filter(line => !logFilter.value || line.toLowerCase().includes(logFilter.value.toLowerCase())).join('\n'))
const logLines = computed(() => filteredLogs.value ? filteredLogs.value.split('\n').filter(Boolean).length : 0)
function podMetric(name: string) { return podMetricMap.value.get(name) }
function metricPercent(value: string | undefined, type: 'cpu' | 'memory') { const number = type === 'cpu' ? cpuNumber(value) : memoryNumber(value); const max = type === 'cpu' ? maxPodCPU.value : maxPodMemory.value; return Math.max(number > 0 ? 4 : 0, Math.round(number / max * 100)) }
function toggleContainer(name: string) { expandedContainers.value[name] = !expandedContainers.value[name] }
function openPod(pod: KubernetesObject) { void router.push({ name: 'kubernetes-pod-detail', query: { cluster_id: clusterID.value, namespace: namespace.value, name: pod.name } }) }

function matchesSelector(item: KubernetesObject) { return Object.entries(selector.value).every(([key, value]) => item.labels?.[key] === value) }
async function load() {
  if (!clusterID.value || !name.value) return
  loading.value = true
  try {
    const [detail, deployments, podResult, eventResult, supportResult] = await Promise.all([
      getKubernetesObject({ cluster_id: clusterID.value, resource: 'deployments', namespace: namespace.value, name: name.value }),
      listKubernetesObjects({ cluster_id: clusterID.value, resource: 'deployments', namespace: namespace.value, keyword: name.value, page: 1, limit: 100 }),
      listKubernetesObjects({ cluster_id: clusterID.value, resource: 'pods', namespace: namespace.value, page: 1, limit: 1000, refresh: true }),
      listKubernetesEvents(clusterID.value, namespace.value),
      getKubernetesDeploymentSupport(clusterID.value, namespace.value, name.value),
    ])
    yaml.value = detail.data.data.yaml
    manifest.value = parse(yaml.value) || {}
    row.value = deployments.data.data.list.find(item => item.name === name.value) || null
    pods.value = podResult.data.data.list.filter(matchesSelector)
    events.value = eventResult.data.data.list
    support.value = supportResult.data.data
    if (!terminalPod.value || !pods.value.some(item => item.name === terminalPod.value)) terminalPod.value = pods.value[0]?.name || ''
    if (!terminalContainer.value || !containers.value.some(item => item.name === terminalContainer.value)) terminalContainer.value = containers.value[0]?.name || ''
  } finally { loading.value = false }
}
async function loadLogs() { if (!pods.value.length || !containers.value.length) return; logsLoading.value = true; try { const podTargets = logPod.value === '__all__' ? pods.value.map(item => item.name) : [logPod.value]; const targets = podTargets.flatMap(pod => containers.value.map(container => ({ pod, container: container.name }))); const results = await Promise.all(targets.map(target => getKubernetesPodLogs({ cluster_id: clusterID.value, namespace: namespace.value, pod: target.pod, container: target.container, tail_lines: logTailLines.value, timestamps: logTimestamps.value }))); logs.value = results.map((result, index) => targets.length > 1 ? `[${targets[index].pod}/${targets[index].container}]\n${result.data.data.logs || ''}` : result.data.data.logs || '').join('\n') } finally { logsLoading.value = false } }
async function runTerminalCommand(value: string) { if (!value.trim() || !terminalPod.value || !terminalContainer.value || !xterm) { xterm?.write('\r\n$ '); return }; commandRunning.value = true; terminalUp.value += new TextEncoder().encode(value).length; try { const { data } = await execKubernetesPodCommand({ cluster_id: clusterID.value, namespace: namespace.value, pod: terminalPod.value, container: terminalContainer.value, command: value }); const output = `${data.data.output || ''}${data.data.error || ''}`; terminalDown.value += new TextEncoder().encode(output).length; xterm.write(`\r\n${output.replace(/\n/g, '\r\n')}${output && !output.endsWith('\n') ? '\r\n' : ''}$ `) } catch (error: any) { xterm.write(`\r\n${error?.response?.data?.message || error?.message || '命令执行失败'}\r\n$ `) } finally { commandRunning.value = false } }
async function initializeTerminal() { await nextTick(); if (!terminalHost.value) return; terminalResizeObserver?.disconnect(); xterm?.dispose(); terminalHost.value.replaceChildren(); terminalBuffer = ''; terminalSessionKey = `${terminalPod.value}/${terminalContainer.value}`; xterm = new Terminal({ cursorBlink: true, fontSize: terminalFontSize.value, lineHeight: 1.25, fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace', theme: { background: '#050505', foreground: '#e7eaf0', cursor: '#f5f5f5', green: '#62e785' }, scrollback: 5000 }); xtermFit = new FitAddon(); xterm.loadAddon(xtermFit); xterm.open(terminalHost.value); xtermFit.fit(); xterm.write('\x1b[32m$ \x1b[0m'); xterm.onData(data => { if (commandRunning.value) return; if (data === '\r') { const value = terminalBuffer; terminalBuffer = ''; void runTerminalCommand(value); return } if (data === '\u007f') { if (terminalBuffer) { terminalBuffer = terminalBuffer.slice(0, -1); xterm?.write('\b \b') }; return } if (data >= ' ') { terminalBuffer += data; xterm?.write(data) } }); terminalResizeObserver = new ResizeObserver(() => xtermFit?.fit()); terminalResizeObserver.observe(terminalHost.value); xterm.focus() }
async function activateTerminal() {
  await nextTick()
  if (!xterm) {
    await initializeTerminal()
    return
  }
  xtermFit?.fit()
  xterm.focus()
}
function clearConsole(target: 'logs' | 'terminal') {
  if (target === 'logs') {
    logs.value = ''
    return
  }
  xterm?.clear()
  xterm?.write('\x1b[32m$ \x1b[0m')
}
async function fullscreenTerminal() { if (!terminalPanel.value) return; if (document.fullscreenElement) await document.exitFullscreen(); else await terminalPanel.value.requestFullscreen(); await nextTick(); xtermFit?.fit() }
function formatTraffic(value: number) { return value < 1024 ? `${value} B/s` : `${(value / 1024).toFixed(1)} KB/s` }
function downloadLogs() { const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([filteredLogs.value], { type: 'text/plain;charset=utf-8' })); link.download = `${name.value}-${logPod.value === '__all__' ? 'all-pods' : logPod.value}.log`; link.click(); URL.revokeObjectURL(link.href) }
async function fullscreenLogs() { if (!logPanel.value) return; if (document.fullscreenElement) await document.exitFullscreen(); else await logPanel.value.requestFullscreen() }
async function saveYAML() {
  saving.value = true
  try { const object = parse(editorYaml.value); await applyKubernetesObject({ cluster_id: clusterID.value, resource: 'deployments', namespace: namespace.value, yaml: editorYaml.value }); yamlDialog.value = false; ElMessage.success(yamlMode.value === 'clone' ? 'Deployment 已克隆' : 'Deployment 已保存'); if (yamlMode.value === 'clone') await router.replace({ name: 'kubernetes-deployment-detail', query: { cluster_id: clusterID.value, namespace: object?.metadata?.namespace || namespace.value, name: object?.metadata?.name } }); await load() } finally { saving.value = false }
}
function editYAML() { yamlMode.value = 'edit'; editorYaml.value = yaml.value; yamlDialog.value = true }
function cloneDeployment() { const object = parse(yaml.value); object.metadata = object.metadata || {}; object.metadata.name = `${name.value}-copy`; delete object.metadata.uid; delete object.metadata.resourceVersion; delete object.metadata.creationTimestamp; editorYaml.value = stringify(object); yamlMode.value = 'clone'; yamlDialog.value = true }
function scale() { scaleReplicas.value = desired.value; scaleDialog.value = true }
async function submitScale() {
  scaleSaving.value = true
  try {
    const object = parse(yaml.value); object.spec = object.spec || {}; object.spec.replicas = scaleReplicas.value
    await applyKubernetesObject({ cluster_id: clusterID.value, resource: 'deployments', namespace: namespace.value, yaml: stringify(object) })
    scaleDialog.value = false
    ElMessage.success('扩缩容成功')
    await load()
  } finally { scaleSaving.value = false }
}
async function restart() {
  await ElMessageBox.confirm(`确认重启 ${name.value}？`, '重启 Deployment')
  const object = parse(yaml.value); object.spec.template.metadata = object.spec.template.metadata || {}; object.spec.template.metadata.annotations = object.spec.template.metadata.annotations || {}; object.spec.template.metadata.annotations['kubectl.kubernetes.io/restartedAt'] = new Date().toISOString()
  await applyKubernetesObject({ cluster_id: clusterID.value, resource: 'deployments', namespace: namespace.value, yaml: stringify(object) }); ElMessage.success('已触发滚动重启'); await load()
}
function remove() { deleteConfirm.value = ''; deleteWait.value = true; deleteForce.value = false; deleteDialog.value = true }
async function confirmRemove() {
  deleting.value = true
  try {
    await deleteKubernetesObject({ cluster_id: clusterID.value, resource: 'deployments', namespace: namespace.value, name: name.value, wait: deleteWait.value, force: deleteForce.value })
    deleteDialog.value = false
    ElMessage.success('删除成功')
    await router.push('/kubernetes/workloads')
  } finally { deleting.value = false }
}
function statusText(status?: string) { return ['Running', 'Available', 'Ready', '可用'].includes(status || '') ? '可用' : status || '未知' }
onMounted(load)
watch(activeTab, value => { if (value === 'logs' && !logs.value) void loadLogs(); if (value === 'terminal') void activateTerminal() })
watch(logPod, () => { if (activeTab.value === 'logs') void loadLogs() })
watch([terminalPod, terminalContainer], ([pod, container]) => {
  const sessionKey = `${pod}/${container}`
  if (!xterm || !pod || !container || terminalSessionKey === sessionKey) return
  terminalBuffer = ''
  terminalSessionKey = sessionKey
  xterm.write(`\r\n\x1b[90m已切换至 ${sessionKey}\x1b[0m\r\n\x1b[32m$ \x1b[0m`)
  if (activeTab.value === 'terminal') void nextTick(() => { xtermFit?.fit(); xterm?.focus() })
})
watch(terminalFontSize, value => { if (xterm) xterm.options.fontSize = value; xtermFit?.fit() })
onBeforeUnmount(() => { terminalResizeObserver?.disconnect(); xterm?.dispose() })
</script>

<template>
  <section v-loading="loading" class="deployment-detail">
    <header class="detail-header">
      <div class="identity"><el-button text :icon="ArrowLeft" @click="router.back()" /><div><h1>{{ name }}</h1><p>Namespace: <b>{{ namespace }}</b></p></div></div>
      <div class="actions"><el-button :icon="Refresh" @click="load">刷新</el-button><el-button :icon="Document" @click="describeDialog=true">描述</el-button><el-button v-permission="'POST /api/v1/kubernetes/resources/apply'" :icon="CopyDocument" @click="cloneDeployment">克隆</el-button><el-button v-permission="'POST /api/v1/kubernetes/resources/apply'" :icon="EditPen" @click="editYAML">编辑 YAML</el-button><el-button v-permission="'POST /api/v1/kubernetes/resources/apply'" :icon="SetUp" @click="scale">扩缩容</el-button><el-button v-permission="'POST /api/v1/kubernetes/resources/apply'" :icon="RefreshRight" @click="restart">重启</el-button><el-button v-permission="'POST /api/v1/kubernetes/resources/delete'" type="danger" :icon="Delete" @click="remove">删除</el-button></div>
    </header>
    <el-tabs v-model="activeTab" class="detail-tabs">
      <el-tab-pane label="概览" name="overview">
        <div class="metric-grid"><article><span>状态</span><strong class="healthy">● {{ statusText(row?.status) }}</strong></article><article><span>期望</span><strong>{{ desired }}</strong><small>副本数</small></article><article><span>就绪</span><strong>{{ ready }}/{{ desired }}</strong><small>副本数</small></article><article><span>最新</span><strong>{{ ready }}</strong><small>副本数</small></article><article><span>可用</span><strong>{{ available }}</strong><small>副本数</small></article><article><span>创建时间</span><strong>{{ row?.age || '-' }}</strong><small>{{ row?.created_at || '-' }}</small></article></div>
        <div class="overview-grid"><main>
          <section class="panel"><h2>Pods ({{ pods.length }})</h2><div class="pod-table"><div class="pod-head"><b>Pods</b><b>状态</b><b>就绪</b><b>重启</b><b>节点</b><b>运行时间</b></div><div v-for="pod in pods" :key="pod.name" class="pod-row"><span><b class="pod-link" @click="openPod(pod)">{{ pod.name }}</b><small>{{ pod.pod_ip || '-' }}</small></span><span class="healthy">● {{ statusText(pod.status) }}</span><span>{{ pod.ready || '-' }}</span><span>{{ pod.restarts ?? 0 }}</span><span>{{ pod.node || '-' }}</span><span>{{ pod.age || '-' }}</span></div><el-empty v-if="!pods.length" description="暂无 Pod" :image-size="48" /></div></section>
          <section class="panel info"><h2>信息</h2><div class="info-summary"><div><span>所有者</span><b class="owner">{{ support.owner || '-' }}</b></div><div><span>Selector</span><code>{{ Object.entries(selector).map(([k,v]) => `${k}=${v}`).join(', ') || '-' }}</code></div></div><h3>镜像</h3><div class="images"><div v-for="container in containers" :key="container.name" class="image-line"><b>{{ container.name }}</b><code>{{ container.image }}</code><span>{{ container.imagePullPolicy || '-' }}</span></div></div><div class="info-grid"><span>策略</span><b>{{ strategy }}</b><span>版本</span><b>{{ support.revision || '-' }}</b><span>最大扩容</span><b>{{ maxSurge }}</b><span>最大不可用</span><b>{{ maxUnavailable }}</b><span>服务账号</span><b>{{ serviceAccount }}</b><span>容器</span><b>{{ containers.length }}</b><span>卷</span><b>{{ volumes }}</b><span>最短就绪时间</span><b>{{ support.min_ready_seconds }}s</b><span>进度截止时间</span><b>{{ support.progress_deadline_seconds == null ? '-' : `${support.progress_deadline_seconds}s` }}</b></div><div class="uid-row"><span>UID</span><code>{{ support.uid || '-' }}</code></div></section>
        </main><aside><section class="panel"><h2>事件 ({{ deploymentEvents.length }})</h2><div v-for="item in deploymentEvents.slice(0, 5)" :key="`${item.reason}-${item.lastTimestamp}`" class="event"><b :class="{ warning: item.type === 'Warning' }">{{ item.reason }}</b><span>{{ item.message }}</span><small>{{ item.lastTimestamp }}</small></div><p v-if="!deploymentEvents.length" class="empty">暂无最近事件</p></section><section class="panel"><h2>标签 ({{ Object.keys(labels).length }})</h2><code v-for="(value,key) in labels" :key="key">{{ key }}={{ value }}</code></section><section class="panel"><h2>注解 ({{ Object.keys(annotations).length }})</h2><code v-for="(value,key) in annotations" :key="key">{{ key }}={{ value }}</code></section></aside></div>
      </el-tab-pane>
      <el-tab-pane :label="`Pods (${pods.length})`" name="pods"><section class="panel pods-panel"><h2>Pods</h2><div class="pods-table"><div class="pods-table-head"><b>Name</b><b>Ready</b><b>Restart</b><b>Status</b><b>CPU</b><b>Memory</b><b>IP</b><b>Node</b><b>Created</b></div><div v-for="pod in pagedPods" :key="pod.name" class="pods-table-row"><b class="pod-name" @click="openPod(pod)">{{ pod.name }}</b><span>{{ pod.ready || '-' }}</span><span>{{ pod.restarts ?? 0 }}</span><span><i class="status-pill">● {{ pod.status }}</i></span><span class="usage"><i><em :style="{ width: `${metricPercent(podMetric(pod.name)?.cpu, 'cpu')}%` }" /></i><small>{{ podMetric(pod.name)?.cpu || '-' }}</small></span><span class="usage"><i><em :style="{ width: `${metricPercent(podMetric(pod.name)?.memory, 'memory')}%` }" /></i><small>{{ podMetric(pod.name)?.memory || '-' }}</small></span><code>{{ pod.pod_ip || '-' }}</code><b class="node-name">{{ pod.node || '-' }}</b><span>{{ pod.created_at || '-' }} ({{ pod.age || '-' }})</span></div></div><el-empty v-if="!pods.length" description="暂无 Pod" :image-size="56" /><div v-else class="pods-pagination"><span>显示 {{ (podPage - 1) * podPageSize + 1 }} - {{ Math.min(podPage * podPageSize, pods.length) }} 条，共 {{ pods.length }} 条</span><el-pagination v-model:current-page="podPage" v-model:page-size="podPageSize" small background layout="prev, pager, next" :total="pods.length" /></div></section></el-tab-pane>
      <el-tab-pane :label="`容器 (${containers.length})`" name="containers"><div class="container-list"><article v-for="container in containers" :key="container.name" class="container-card"><header><b>{{ container.name }}</b><el-button v-permission="'POST /api/v1/kubernetes/resources/apply'" text :icon="EditPen" title="编辑容器 YAML" @click="editYAML" /></header><div class="container-main"><div><span>IMAGE</span><code>{{ container.image }}</code></div><div><span>IMAGE PULL POLICY</span><code>{{ container.imagePullPolicy || '-' }}</code></div></div><button class="expand-button" @click="toggleContainer(container.name)">{{ expandedContainers[container.name] ? '⌃ 收起' : '⌄ 展开更多' }}</button><div v-if="expandedContainers[container.name]" class="container-extra"><div><span>COMMAND</span><code>{{ [...(container.command || []), ...(container.args || [])].join(' ') || '-' }}</code></div><div><span>RESOURCES</span><code>CPU {{ container.resources?.requests?.cpu || '-' }} / {{ container.resources?.limits?.cpu || '-' }}　Memory {{ container.resources?.requests?.memory || '-' }} / {{ container.resources?.limits?.memory || '-' }}</code></div><div><span>ENVIRONMENT</span><code>{{ (container.env || []).map((item:any) => `${item.name}=${item.value ?? '[引用]'}`).join('　') || '-' }}</code></div></div><footer><span>PORTS</span><div><code v-for="port in container.ports || []" :key="`${port.containerPort}-${port.protocol}`">{{ port.containerPort }}</code><i v-for="port in container.ports || []" :key="`protocol-${port.containerPort}-${port.protocol}`">{{ port.protocol || 'TCP' }}</i><small v-if="!container.ports?.length">未配置</small></div></footer></article><el-empty v-if="!containers.length" description="暂无容器" /></div></el-tab-pane>
      <el-tab-pane label="YAML" name="yaml"><KubernetesYamlEditor :model-value="yaml" min-height="calc(100vh - 210px)" readonly /></el-tab-pane>
      <el-tab-pane label="日志" name="logs"><section ref="logPanel" class="log-panel"><header><div class="log-title"><b>Logs</b><span>{{ logLines }} 行</span><i :class="{ loading: logsLoading }" /></div><div class="log-actions"><el-input v-model="logFilter" placeholder="过滤日志…" clearable /><el-select v-model="logPod" class="pod-select" filterable placeholder="搜索 Pod…" popper-class="pod-select-dropdown"><el-option label="全部 Pod" value="__all__"><div class="pod-option"><b>全部 Pod</b><span>聚合当前工作负载的所有 Pod 日志</span></div></el-option><el-option v-for="pod in pods" :key="pod.name" :label="pod.name" :value="pod.name"><div class="pod-option"><b>{{ pod.name }}</b><span>运行 {{ pod.age || '-' }}，节点 {{ pod.node || '-' }}</span></div></el-option></el-select><el-popover placement="bottom-end" :width="280" trigger="click"><template #reference><el-button :icon="Setting" title="日志设置" /></template><div class="log-settings"><label><span>Tail Lines</span><el-select v-model="logTailLines" @change="loadLogs"><el-option label="100" :value="100" /><el-option label="200" :value="200" /><el-option label="500" :value="500" /><el-option label="1000" :value="1000" /><el-option label="全部" :value="0" /></el-select></label><label><span>显示时间戳</span><el-switch v-model="logTimestamps" @change="loadLogs" /></label><label><span>字体大小</span><el-input-number v-model="logFontSize" :min="10" :max="24" :step="1" controls-position="right" /></label></div></el-popover><el-button title="自动换行" :class="{ active: logWrap }" @click="logWrap=!logWrap">↵</el-button><el-button title="切换日志配色" :class="{ active: logGreen }" @click="logGreen=!logGreen">◉</el-button><el-button title="清屏" @click="clearConsole('logs')">≡</el-button><el-button :icon="Download" title="下载日志" @click="downloadLogs" /><el-button :icon="FullScreen" title="全屏" @click="fullscreenLogs" /></div></header><pre :class="['console','log-console',{ wrap:logWrap,green:logGreen }]" :style="{ fontSize: `${logFontSize}px` }">{{ filteredLogs || '暂无日志' }}</pre></section></el-tab-pane>
      <el-tab-pane label="终端" name="terminal"><section ref="terminalPanel" class="pod-terminal"><header><div class="terminal-title"><b>&gt;_　Terminal</b><i /><span class="up">↑ {{ formatTraffic(terminalUp) }}</span><span class="down">↓ {{ formatTraffic(terminalDown) }}</span></div><div class="terminal-actions"><el-select v-model="terminalPod" class="pod-select" filterable placeholder="搜索 Pod…" popper-class="pod-select-dropdown"><el-option v-for="pod in pods" :key="pod.name" :label="pod.name" :value="pod.name"><div class="pod-option"><b>{{ pod.name }}</b><span>运行 {{ pod.age || '-' }}，节点 {{ pod.node || '-' }}</span></div></el-option></el-select><el-popover placement="bottom-end" :width="240" trigger="click"><template #reference><el-button :icon="Setting" title="终端设置" /></template><div class="log-settings"><label><span>字体大小</span><el-input-number v-model="terminalFontSize" :min="10" :max="24" controls-position="right" /></label></div></el-popover><el-button title="清屏" @click="clearConsole('terminal')">≡</el-button><el-button :icon="FullScreen" title="全屏" @click="fullscreenTerminal" /></div></header><div ref="terminalHost" class="xterm-host" /></section></el-tab-pane>
      <el-tab-pane :label="`相关资源 (${pods.length + support.related.length})`" name="related"><section class="panel"><div v-for="item in support.related" :key="`${item.kind}-${item.name}`" class="list-row"><b>{{ item.kind }}</b><span>{{ item.name }}</span><span>{{ item.status }}</span></div><div v-for="pod in pods" :key="pod.name" class="list-row"><b>Pod</b><span>{{ pod.name }}</span><span>{{ pod.status }}</span></div></section></el-tab-pane>
      <el-tab-pane :label="`历史 (${support.history.length})`" name="history"><div class="history-tabs"><b>发布版本历史</b></div><section class="panel history-panel"><div class="history-table"><div class="history-head"><b>版本</b><b>ReplicaSet</b><b>副本数</b><b>创建时间</b><b>容器</b><b>变更原因</b><b>操作</b></div><div v-for="item in pagedHistory" :key="item.name" class="history-row"><strong>{{ item.revision || '-' }}</strong><b>{{ item.name }}</b><span>{{ item.replicas }}</span><span>{{ item.created_at || '-' }}</span><div class="history-images"><code v-for="image in item.images" :key="image">{{ image }}</code><span v-if="!item.images.length">-</span></div><span>{{ item.change_reason || '-' }}</span><el-button v-if="item.revision === support.revision" disabled>当前</el-button><span v-else class="history-version">历史版本</span></div></div><el-empty v-if="!sortedHistory.length" description="暂无发布历史" :image-size="56" /><div v-else class="history-pagination"><span>显示 {{ (historyPage - 1) * historyPageSize + 1 }} - {{ Math.min(historyPage * historyPageSize, sortedHistory.length) }} 条，共 {{ sortedHistory.length }} 条</span><el-pagination v-model:current-page="historyPage" v-model:page-size="historyPageSize" small background layout="prev, pager, next" :total="sortedHistory.length" /></div></section></el-tab-pane>
      <el-tab-pane :label="`事件 (${deploymentEvents.length})`" name="events"><section class="panel"><div v-for="item in deploymentEvents" :key="`${item.reason}-${item.lastTimestamp}`" class="list-row"><b>{{ item.reason }}</b><span>{{ item.message }}</span><span>{{ item.count }} 次</span><span>{{ item.lastTimestamp }}</span></div></section></el-tab-pane>
      <el-tab-pane :label="`监控 (${support.metrics.length})`" name="monitor"><section class="metric-list"><article v-for="item in support.metrics" :key="item.pod"><b>{{ item.pod }}</b><span>CPU <strong>{{ item.cpu }}</strong></span><span>内存 <strong>{{ item.memory }}</strong></span></article><el-empty v-if="!support.metrics.length" description="Metrics Server 暂无指标" /></section></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="describeDialog" title="Deployment 描述" width="min(800px,calc(100vw - 32px))" align-center class="deployment-detail-dialog"><div class="describe-command">kubectl describe deployment -n {{ namespace }} {{ name }}</div><pre class="describe-output">{{ support.description || '暂无描述信息' }}</pre></el-dialog>
    <el-dialog v-model="scaleDialog" title="扩缩容 Deployment" width="min(440px,calc(100vw - 16px))" align-center class="scale-dialog"><p>调整此 Deployment 的副本数。</p><label>副本数</label><el-input-number v-model="scaleReplicas" :min="0" :step="1" :precision="0" /><el-button type="primary" :icon="SetUp" :loading="scaleSaving" @click="submitScale">扩缩容</el-button></el-dialog>
    <el-dialog v-model="deleteDialog" width="min(500px,calc(100vw - 32px))" align-center class="delete-resource-dialog"><template #header><div class="delete-title"><span><el-icon><WarningFilled /></el-icon></span><div><b>删除 deployments</b><small>此操作不可撤销。</small></div></div></template><section class="delete-summary"><b>即将删除：</b><dl><dt>名称:</dt><dd>{{ name }}</dd><dt>类型:</dt><dd>deployments</dd><dt>Namespace:</dt><dd>{{ namespace }}</dd></dl></section><label class="delete-confirm">输入 <b>{{ name }}</b> 以确认：<el-input v-model="deleteConfirm" :placeholder="name" autocomplete="off" /></label><el-checkbox v-model="deleteWait">等待</el-checkbox><div class="force-delete"><el-checkbox v-model="deleteForce">强制删除（Grace Period 设为 0）</el-checkbox><small>强制删除会立即终止资源，请仅在资源无法正常删除时使用。</small></div><div class="delete-actions"><el-button :disabled="deleting" @click="deleteDialog=false">取消</el-button><el-button type="danger" :icon="Delete" :loading="deleting" :disabled="deleteConfirm !== name" @click="confirmRemove">删除</el-button></div></el-dialog>
    <el-dialog v-model="yamlDialog" :title="yamlMode === 'clone' ? '克隆 Deployment' : '编辑 Deployment YAML'" width="min(800px,calc(100vw - 32px))" align-center destroy-on-close class="deployment-detail-dialog"><KubernetesYamlEditor v-model="editorYaml" /><template #footer><el-button @click="yamlDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveYAML">{{ yamlMode === 'clone' ? '创建副本' : '保存' }}</el-button></template></el-dialog>
  </section>
</template>

